import{_ as o,o as a,c as t,a0 as d}from"./chunks/framework.jwovEGr5.js";const m=JSON.parse('{"title":"Accessibility — sharecli","description":"","frontmatter":{},"headers":[],"relativePath":"a11y/README.md","filePath":"a11y/README.md"}'),r={name:"a11y/README.md"};function s(c,e,i,l,n,h){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="accessibility-—-sharecli" tabindex="-1">Accessibility — sharecli <a class="header-anchor" href="#accessibility-—-sharecli" aria-label="Permalink to &quot;Accessibility — sharecli&quot;">​</a></h1><p><strong>Compliance posture:</strong> WCAG 2.2 <strong>Level A</strong> for the embedded web dashboard; <strong>dev-AX Level A</strong> for CLI/TUI surfaces (structured output, non-color degradation, keyboard exits).</p><p>sharecli is primarily a developer-facing CLI with three human-visible surfaces:</p><table tabindex="0"><thead><tr><th>Surface</th><th>Path</th><th>Level A posture</th></tr></thead><tbody><tr><td>Web dashboard</td><td><code>src/dashboard.html</code> (served at <code>/</code> by <code>sharecli serve</code>)</td><td>Semantic landmarks (<code>nav</code>, <code>main</code>), <code>lang=&quot;en&quot;</code>, live status regions; see <code>tests/a11y/</code></td></tr><tr><td>Thermal TUI</td><td><code>crates/sharecli-thermal-tui</code></td><td>Keyboard-only operation (<code>q</code>, <code>Ctrl-C</code>); text labels alongside color (GREEN/YELLOW/RED)</td></tr><tr><td>CLI stdout/stderr</td><td><code>src/main.rs</code></td><td><code>NO_COLOR</code> honored; <code>--json</code> / <code>--format json</code> machine-readable modes; plain-language errors</td></tr></tbody></table><h2 id="wcag-2-2-level-a-—-cli-tui" tabindex="-1">WCAG 2.2 Level A — CLI &amp; TUI <a class="header-anchor" href="#wcag-2-2-level-a-—-cli-tui" aria-label="Permalink to &quot;WCAG 2.2 Level A — CLI &amp; TUI&quot;">​</a></h2><p>The following Level A expectations apply to terminal surfaces (adapted from WCAG 1.4.1, 1.3.1, 2.1.1):</p><ol><li><strong>Use of color (1.4.1):</strong> Thermal state and process status expose text labels, not color alone (<code>level_label</code>, table columns). Set <code>NO_COLOR=1</code> or <code>TERM=dumb</code> to disable ANSI styling.</li><li><strong>Info and relationships (1.3.1):</strong> <code>sharecli ps</code> prints fixed column headers; <code>sharecli list --json</code> returns structured fields.</li><li><strong>Keyboard (2.1.1):</strong> TUI is fully operable without a mouse; see <a href="./keyboard.html"><code>keyboard.md</code></a>.</li><li><strong>Timing adjustable (2.2.1):</strong> TUI polls on a fixed interval; user can exit immediately with <code>q</code> or <code>Ctrl-C</code>.</li></ol><p>Automated enforcement for the dashboard:</p><ul><li><strong>Rust (CI via <code>cargo test</code>):</strong> <code>tests/a11y/dashboard_landmarks.rs</code> — landmark + <code>lang</code> assertions.</li><li><strong>axe-core (CI via <code>.github/workflows/a11y.yml</code>):</strong> <code>scripts/a11y/axe-dashboard.mjs</code> scans <code>src/dashboard.html</code> with jsdom (no browser). Tags <strong><code>wcag2a</code></strong>, <strong><code>wcag21a</code></strong>, <strong><code>wcag22a</code></strong> (WCAG 2.x Level A). The job <strong>hard-fails</strong> on <strong>serious/critical</strong> violations; moderate/minor are logged only.</li></ul><p>Run locally: <code>npm ci &amp;&amp; npm run a11y:dashboard</code>.</p><h2 id="degraded-mode-operation" tabindex="-1">Degraded-mode operation <a class="header-anchor" href="#degraded-mode-operation" aria-label="Permalink to &quot;Degraded-mode operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td><code>NO_COLOR</code> set</td><td>Theme ANSI suppressed; output remains readable plain text</td></tr><tr><td><code>TERM=dumb</code></td><td>No escape sequences assumed; use <code>--json</code> where available</td></tr><tr><td>WebSocket disconnect</td><td>Dashboard shows <code>disconnected — reconnecting in 3s</code> and auto-retries</td></tr><tr><td>Thermal governor unavailable</td><td>TUI falls back to <code>ThermalLevel::Green</code> and continues polling</td></tr></tbody></table><p>See <a href="./status-and-recovery.html"><code>status-and-recovery.md</code></a> for FR-004 health surfaces and error-recovery patterns.</p><h2 id="related-docs" tabindex="-1">Related docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related docs&quot;">​</a></h2><ul><li><a href="./contrast.html">Color contrast ratios</a> — Backbone-2 tokens (<code>assets/tokens.css</code>, <code>src/theme.rs</code>)</li><li><a href="./keyboard.html">Keyboard bindings</a> — TUI quit keys and dashboard focus order</li><li><a href="./responsive.html">Responsive layout</a> — TUI compact mode + dashboard 375/768 breakpoints</li><li><a href="./status-and-recovery.html">Status &amp; recovery</a> — health endpoints, validation hints, degraded mode</li></ul><h2 id="screen-reader-assistive-tech-checklist-manual" tabindex="-1">Screen-reader / assistive-tech checklist (manual) <a class="header-anchor" href="#screen-reader-assistive-tech-checklist-manual" aria-label="Permalink to &quot;Screen-reader / assistive-tech checklist (manual)&quot;">​</a></h2><ol><li><strong>Dashboard:</strong> VoiceOver/NVDA — verify <code>nav</code> announces connection status; <code>main</code> table headers are read in order.</li><li><strong>CLI:</strong> Run <code>sharecli list --json</code> and pipe to your tooling; avoid parsing colorized <code>ps</code> output.</li><li><strong>Tray (macOS):</strong> <code>accessibilityDescription: &quot;ShareCLI&quot;</code> on menu-bar icon (<code>desktop/ShareCLITray</code>).</li></ol>',17)])])}const b=o(r,[["render",s]]);export{m as __pageData,b as default};
